func MaxBy[T any, U cmp.Ordered](s []T, f func(T) U) T {
	if len(s) == 0 {
		var zero T
		return zero
	}
	best := s[0]
	maxKey := f(s[0])
	for _, v := range s[1:] {
		key := f(v)
		if key > maxKey {
			maxKey = key
			best = v
		}
	}
	return best
}

