	res := NewSet[T]()
	for k := range s.data {
		res.Add(k)
	}
	for k := range other.data {
		res.Add(k)
	}
	return res
}

func (s *Set[T]) Intersection(other *Set[T]) *Set[T] {
	res := NewSet[T]()
	for k := range s.data {
		if other.Contains(k) {
			res.Add(k)
		}
	}
	return res
}

func (s *Set[T]) ToSlice() []T {
	res := make([]T, 0, len(s.data))
	for k := range s.data {
		res = append(res, k)
	}
	return res
}

