func (s *Stack[T]) Push(v T) { s.data = append(s.data, v) }

func (s *Stack[T]) Pop() (T, bool) {
	if len(s.data) == 0 {
		var zero T
		return zero, false
	}
	idx := len(s.data) - 1
	v := s.data[idx]
	s.data = s.data[:idx]
	return v, true
}

