package main

import "fmt"

// --- 1. Интерфейсы: Динамический полиморфизм (Runtime) ---
type Notifier interface {
	Notify(msg string)
}

type EmailNotifier struct{}

func (EmailNotifier) Notify(msg string) { fmt.Println("[Email]", msg) }

type SMSNotifier struct{}

func (SMSNotifier) Notify(msg string) { fmt.Println("[SMS]", msg) }

// Гетерогенная коллекция разных типов:
func SendAll(notifiers []Notifier, msg string) {
	for _, n := range notifiers {
		n.Notify(msg) // Динамический вызов через itab
	}
}

// --- 2. Дженерики: Статический полиморфизм (Compile-time) ---
func Deduplicate[T comparable](items []T) []T {
	seen := make(map[T]struct{})
	var res []T
	for _, item := range items {
		if _, ok := seen[item]; !ok {
			seen[item] = struct{}{}
			res = append(res, item)
		}
	}
	return res
}

func main() {
	// 1. Интерфейсы идеальны для разнородных реализаций:
	services := []Notifier{EmailNotifier{}, SMSNotifier{}}
	SendAll(services, "Сервер запущен!")

	// 2. Дженерики идеальны для алгоритмов и структур данных:
	ints := Deduplicate([]int{1, 2, 2, 3, 1})
	fmt.Println("Deduplicate int:", ints)
}

package main

import (
	"cmp"
	"fmt"
)

type Heap[T cmp.Ordered] struct {
	items []T
}

func (h *Heap[T]) Insert(v T) {
	h.items = append(h.items, v)
	i := len(h.items) - 1
	for i > 0 {
		parent := (i - 1) / 2
		if h.items[i] < h.items[parent] {
			h.items[i], h.items[parent] = h.items[parent], h.items[i]
			i = parent
		} else {
			break
		}
	}
}

func (h *Heap[T]) ExtractMin() (T, bool) {
	if len(h.items) == 0 {
		var zero T
		return zero, false
	}
	min := h.items[0]
	last := len(h.items) - 1
	h.items[0] = h.items[last]
	h.items = h.items[:last]

	i := 0
	n := len(h.items)
	for {
		left := 2*i + 1
		right := 2*i + 2
		smallest := i

		if left < n && h.items[left] < h.items[smallest] {
			smallest = left
		}
		if right < n && h.items[right] < h.items[smallest] {
			smallest = right
		}
		if smallest != i {
			h.items[i], h.items[smallest] = h.items[smallest], h.items[i]
			i = smallest
		} else {
			break
		}
	}
	return min, true
}

func (h *Heap[T]) Len() int { return len(h.items) }

func main() {
	h := &Heap[int]{}
	h.Insert(50)
	h.Insert(10)
	h.Insert(30)
	h.Insert(5)

	fmt.Print("Извлечение из кучи: ")
	for h.Len() > 0 {
		v, _ := h.ExtractMin()
		fmt.Printf("%d ", v)
	}
	fmt.Println()
}

